/**
 * {@link LeoOperatorKey} must be collision-free over the whole operator tree: two structurally different operators must
 * never share a learning key, otherwise store-wide learned corrections leak between unrelated operators (review finding
 * 3.7.2). Order-independence of the key is a hit-rate optimisation and is never obtained by dropping variable linkage
 * or operator parameters.
 */
class LeoOperatorKeyCollisionTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	// ---------------------------------------------------------------- join surfaces beyond the exhaustive budget

	@Test
	void sevenFactorConnectedChainAndCartesianTriangleTimesChainMustNotShareAKey() {
		// connected 7-edge chain a-b-c-d-e-f-g-h
		TupleExpr chain = leftDeep(p("a", "b"), p("b", "c"), p("c", "d"), p("d", "e"), p("e", "f"), p("f", "g"),
				p("g", "h"));
		// triangle a-b-c-a that is DISCONNECTED from chain d-e-f-g-h: a Cartesian product
		TupleExpr crossProduct = leftDeep(p("a", "b"), p("b", "c"), p("c", "a"), p("d", "e"), p("e", "f"),
				p("f", "g"), p("g", "h"));
		Join chainRoot = (Join) chain;
		Join crossRoot = (Join) crossProduct;
		// LMDB's OperatorKey adds only top-level left/right/shared binding names; show they are identical too.
		assertEquals(chainRoot.getLeftArg().getBindingNames(), crossRoot.getLeftArg().getBindingNames());
		assertEquals(chainRoot.getRightArg().getBindingNames(), crossRoot.getRightArg().getBindingNames());

		LeoOperatorKey chainKey = LeoOperatorKey.from(chain, "", LeoOperatorKey.ConstantMode.EXACT);
		LeoOperatorKey crossKey = LeoOperatorKey.from(crossProduct, "", LeoOperatorKey.ConstantMode.EXACT);
		assertNotEquals(chainKey, crossKey,
				"a connected chain and a Cartesian product must not share learned feedback; fingerprint="
						+ chainKey.structuralFingerprint());
	}

	@Test
	void sevenFactorJoinKeysAreDeterministicAndDistinguishEveryNonIsomorphicShape() {
		Map<String, TupleExpr> shapes = new LinkedHashMap<>();
		shapes.put("chain", leftDeep(p("a", "b"), p("b", "c"), p("c", "d"), p("d", "e"), p("e", "f"), p("f", "g"),
				p("g", "h")));
		shapes.put("star", leftDeep(p("a", "b"), p("a", "c"), p("a", "d"), p("a", "e"), p("a", "f"), p("a", "g"),
				p("a", "h")));
		shapes.put("cycle", leftDeep(p("a", "b"), p("b", "c"), p("c", "d"), p("d", "e"), p("e", "f"), p("f", "g"),
				p("g", "a")));
		shapes.put("cross", leftDeep(p("a", "b"), p("b", "c"), p("c", "a"), p("d", "e"), p("e", "f"), p("f", "g"),
				p("g", "h")));
		shapes.put("two-chains", leftDeep(p("a", "b"), p("b", "c"), p("c", "d"), p("x", "y"), p("y", "z"),
				p("z", "w"), p("w", "v")));
		shapes.put("chain-with-back-edge", leftDeep(p("a", "b"), p("b", "c"), p("c", "d"), p("d", "e"), p("e", "f"),
				p("f", "g"), p("g", "c")));

		Map<String, String> fingerprints = new LinkedHashMap<>();
		for (Map.Entry<String, TupleExpr> shape : shapes.entrySet()) {
			String first = LeoOperatorKey.from(shape.getValue()).structuralFingerprint();
			String second = LeoOperatorKey.from(shape.getValue().clone()).structuralFingerprint();
			assertEquals(first, second, "the key of a " + shape.getKey() + " join must be deterministic");
			fingerprints.put(shape.getKey(), first);
		}
		List<String> names = new ArrayList<>(fingerprints.keySet());
		for (int i = 0; i < names.size(); i++) {
			for (int j = i + 1; j < names.size(); j++) {
				assertNotEquals(fingerprints.get(names.get(i)), fingerprints.get(names.get(j)),
						names.get(i) + " and " + names.get(j) + " are not isomorphic and must not share a key");
			}
		}
	}

	@Test
	void sevenFactorJoinKeyIsIndependentOfTheInputOrderForARenamedTree() {
		TupleExpr chain = leftDeep(p("a", "b"), p("b", "c"), p("c", "d"), p("d", "e"), p("e", "f"), p("f", "g"),
				p("g", "h"));
		TupleExpr renamed = leftDeep(p("q", "r"), p("r", "s"), p("s", "t"), p("t", "u"), p("u", "v"), p("v", "w"),
				p("w", "x"));
		assertEquals(LeoOperatorKey.from(chain), LeoOperatorKey.from(renamed),
				"alpha-renaming must not change the key of a join beyond the exhaustive budget");
	}

	// ---------------------------------------------------------------- conditions must see the join's ordinals

	@Test
	void filterConditionVariablesMustStayLinkedToTheFilteredJoin() {
		Join join = new Join(p("a", "b"), q("b", "c"));
		Filter onJoinVariable = new Filter(join.clone(), new Compare(Var.of("a"), Var.of("b"), Compare.CompareOp.EQ));
		Filter onOtherVariable = new Filter(join.clone(),
				new Compare(Var.of("a"), Var.of("c"), Compare.CompareOp.EQ));

		LeoOperatorKey first = LeoOperatorKey.from(onJoinVariable, "", LeoOperatorKey.ConstantMode.EXACT);
		LeoOperatorKey second = LeoOperatorKey.from(onOtherVariable, "", LeoOperatorKey.ConstantMode.EXACT);
		assertNotEquals(first, second,
				"FILTER(?a=?b) and FILTER(?a=?c) over the same join are different predicates; key="
						+ first.structuralFingerprint());
	}

	@Test
	void filterOverUnionMustDistinguishConditionsOnDifferentBranchVariables() {
		Union union = new Union(p("s", "left"), q("s", "right"));
		Filter onLeft = new Filter(union.clone(),
				new Compare(Var.of("left"), new ValueConstant(VF.createLiteral(1)), Compare.CompareOp.GT));
		Filter onRight = new Filter(union.clone(),
				new Compare(Var.of("right"), new ValueConstant(VF.createLiteral(1)), Compare.CompareOp.GT));

		assertNotEquals(LeoOperatorKey.from(onLeft), LeoOperatorKey.from(onRight),
				"a filter on the left branch's variable must not share a key with a filter on the right branch's");
	}

	@Test
	void leftJoinConditionReferencingLeftVersusRightVariablesMustDiffer() {
		StatementPattern left = p("s", "leftValue");
		StatementPattern right = q("s", "rightValue");
		LeftJoin onLeftValue = new LeftJoin(left.clone(), right.clone(),
				new Compare(Var.of("leftValue"), new ValueConstant(VF.createLiteral(5)), Compare.CompareOp.LT));
		LeftJoin onRightValue = new LeftJoin(left.clone(), right.clone(),
				new Compare(Var.of("rightValue"), new ValueConstant(VF.createLiteral(5)), Compare.CompareOp.LT));

		assertNotEquals(LeoOperatorKey.from(onLeftValue), LeoOperatorKey.from(onRightValue),
				"an OPTIONAL condition on the left side must not share a key with one on the right side");
	}

	// ---------------------------------------------------------------- unary operators must carry their parameters

	@Test
	void distinctOverDifferentProjectionsMustNotShareAStructuralFingerprint() {
		Join join = new Join(p("s", "o"), q("o", "z"));
		Distinct distinctSubject = new Distinct(new Projection(join.clone(), new ProjectionElemList(
				new ProjectionElem("s"))));
		Distinct distinctSubjectObject = new Distinct(new Projection(join.clone(), new ProjectionElemList(
				new ProjectionElem("s"), new ProjectionElem("o"))));

		LeoOperatorKey first = LeoOperatorKey.from(distinctSubject, "", LeoOperatorKey.ConstantMode.EXACT);
		LeoOperatorKey second = LeoOperatorKey.from(distinctSubjectObject, "", LeoOperatorKey.ConstantMode.EXACT);
		// LMDB persists operatorType + structuralFingerprint (+ empty displayBindings for unary operators).
		assertEquals(first.operatorType(), second.operatorType());
		assertNotEquals(first.structuralFingerprint(), second.structuralFingerprint(),
				"DISTINCT ?s and DISTINCT ?s ?o have different multipliers but share the LMDB learning key");
	}

	@Test
	void projectionAliasesAreOrderIndependentButRenameSensitive() {
		Join join = new Join(p("s", "o"), q("o", "z"));
		Projection first = new Projection(join.clone(),
				new ProjectionElemList(new ProjectionElem("s"), new ProjectionElem("o", "renamed")));
		Projection reordered = new Projection(join.clone(),
				new ProjectionElemList(new ProjectionElem("o", "renamed"), new ProjectionElem("s")));
		Projection otherAlias = new Projection(join.clone(),
				new ProjectionElemList(new ProjectionElem("s", "renamed"), new ProjectionElem("o")));

		assertEquals(LeoOperatorKey.from(first).structuralFingerprint(),
				LeoOperatorKey.from(reordered).structuralFingerprint());
		assertNotEquals(LeoOperatorKey.from(first).structuralFingerprint(),
				LeoOperatorKey.from(otherAlias).structuralFingerprint());
	}

	@Test
	void extensionExpressionsArePartOfTheKey() {
		StatementPattern source = p("s", "a");
		Extension plusOne = new Extension(source.clone(), new ExtensionElem(
				new MathExpr(Var.of("a"), new ValueConstant(VF.createLiteral(1)), MathExpr.MathOp.PLUS), "b"));
		Extension timesTwo = new Extension(source.clone(), new ExtensionElem(
				new MathExpr(Var.of("a"), new ValueConstant(VF.createLiteral(2)), MathExpr.MathOp.MULTIPLY), "b"));

		assertNotEquals(LeoOperatorKey.from(plusOne).structuralFingerprint(),
				LeoOperatorKey.from(timesTwo).structuralFingerprint(),
				"BIND(?a+1) and BIND(?a*2) produce different bindings and must not share a key");
	}

	@Test
	void groupKeysAndAggregatesArePartOfTheKey() {
		Join join = new Join(p("s", "o"), q("o", "z"));
		Group bySubject = new Group(join.clone(), Set.of("s"),
				List.of(new GroupElem("count", new Count(Var.of("o")))));
		Group bySubjectAndObject = new Group(join.clone(), Set.of("s", "o"),
				List.of(new GroupElem("count", new Count(Var.of("z")))));
		Group bySubjectDistinctCount = new Group(join.clone(), Set.of("s"),
				List.of(new GroupElem("count", new Count(Var.of("o"), true))));

		assertNotEquals(LeoOperatorKey.from(bySubject).structuralFingerprint(),
				LeoOperatorKey.from(bySubjectAndObject).structuralFingerprint(),
				"GROUP BY ?s and GROUP BY ?s ?o have different output cardinalities");
		assertNotEquals(LeoOperatorKey.from(bySubject).structuralFingerprint(),
				LeoOperatorKey.from(bySubjectDistinctCount).structuralFingerprint(),
				"COUNT(?o) and COUNT(DISTINCT ?o) must not share a key");
	}

	@Test
	void sliceBoundsArePartOfTheKey() {
		StatementPattern source = p("s", "o");
		Slice limitTen = new Slice(source.clone(), 0L, 10L);
		Slice limitTwenty = new Slice(source.clone(), 0L, 20L);
		Slice offsetTen = new Slice(source.clone(), 10L, 10L);

		assertNotEquals(LeoOperatorKey.from(limitTen).structuralFingerprint(),
				LeoOperatorKey.from(limitTwenty).structuralFingerprint(), "LIMIT 10 and LIMIT 20 must differ");
		assertNotEquals(LeoOperatorKey.from(limitTen).structuralFingerprint(),
				LeoOperatorKey.from(offsetTen).structuralFingerprint(), "OFFSET must be part of the key");
	}

	@Test
	void orderDirectionAndExpressionArePartOfTheKey() {
		Join join = new Join(p("s", "o"), q("o", "z"));
		Order ascending = new Order(join.clone(), new OrderElem(Var.of("o"), true));
		Order descending = new Order(join.clone(), new OrderElem(Var.of("o"), false));
		Order byOtherVariable = new Order(join.clone(), new OrderElem(Var.of("z"), true));

		assertNotEquals(LeoOperatorKey.from(ascending).structuralFingerprint(),
				LeoOperatorKey.from(descending).structuralFingerprint(), "ASC and DESC must differ");
		assertNotEquals(LeoOperatorKey.from(ascending).structuralFingerprint(),
				LeoOperatorKey.from(byOtherVariable).structuralFingerprint(),
				"ORDER BY ?o and ORDER BY ?z must differ");
	}

	// ---------------------------------------------------------------- operators that are neither unary nor binary

	@Test
	void tripleRefVariablesMustStayLinkedToTheJoin() {
		// <<?s <urn:p> ?o>> ?x . ?x <urn:q> ?s (linked through ?s) versus ... ?x <urn:q> ?z (unlinked)
		TripleRef linkedRef = new TripleRef(Var.of("s"), Var.of("_const_p", VF.createIRI("urn:p")), Var.of("o"),
				Var.of("x"));
		TripleRef unlinkedRef = new TripleRef(Var.of("s"), Var.of("_const_p", VF.createIRI("urn:p")), Var.of("o"),
				Var.of("x"));
		Join linked = new Join(linkedRef, q("x", "s"));
		Join unlinked = new Join(unlinkedRef, q("x", "z"));

		// LMDB persists only operatorType + structuralFingerprint, so the output mask cannot be relied upon.
		assertNotEquals(LeoOperatorKey.from(linked).structuralFingerprint(),
				LeoOperatorKey.from(unlinked).structuralFingerprint(),
				"a TripleRef must contribute its subject/predicate/object/expression variables; key="
						+ LeoOperatorKey.from(linked).structuralFingerprint());
	}

	// ---------------------------------------------------------------- VALUES tables

	@Test
	void largeValuesTablesWithDifferentRowsMustNotCollide() {
		// "Aa" and "BB" have identical String.hashCode(); VALUES tables beyond 32 rows are keyed by 32-bit hashes.
		BindingSetAssignment first = values("Aa");
		BindingSetAssignment second = values("BB");
		LeoOperatorKey firstKey = LeoOperatorKey.from(first, "", LeoOperatorKey.ConstantMode.EXACT);
		LeoOperatorKey secondKey = LeoOperatorKey.from(second, "", LeoOperatorKey.ConstantMode.EXACT);
		assertNotEquals(firstKey, secondKey,
				"different VALUES contents must not share an EXACT learning key; key="
						+ firstKey.structuralFingerprint());
	}

	@Test
	void largeValuesTablesAreRowOrderIndependentButRowSensitive() {
		List<String> labels = new ArrayList<>();
		for (int i = 0; i < 40; i++) {
			labels.add("row-" + i);
		}
		List<String> shuffled = new ArrayList<>(labels);
		Collections.reverse(shuffled);
		List<String> oneDifferent = new ArrayList<>(labels);
		oneDifferent.set(17, "row-17-changed");

		String ordered = LeoOperatorKey.from(valuesOf(labels)).structuralFingerprint();
		String reordered = LeoOperatorKey.from(valuesOf(shuffled)).structuralFingerprint();
		String changed = LeoOperatorKey.from(valuesOf(oneDifferent)).structuralFingerprint();

		assertEquals(ordered, reordered, "the same rows in a different order must produce the same key");
		assertNotEquals(ordered, changed, "one differing row must change the key");
	}

	@Test
	void separatorCharactersInsideConstantsCannotForgeStructure() {
		// One cell whose label contains the fingerprint separators must not read as two rows {"a","b"}.
		String forged = "a|lang=|dt=http://www.w3.org/2001/XMLSchema#string;literal:b";
		BindingSetAssignment singleForgedRow = valuesOf(List.of(forged));
		BindingSetAssignment twoRows = valuesOf(List.of("a", "b"));

		assertNotEquals(LeoOperatorKey.from(singleForgedRow).structuralFingerprint(),
				LeoOperatorKey.from(twoRows).structuralFingerprint(),
				"a constant containing separators must not produce the fingerprint of a different table");
	}

	// ---------------------------------------------------------------- helpers

	private static BindingSetAssignment values(String collidingLabel) {
		List<String> labels = new ArrayList<>();
		labels.add(collidingLabel);
		for (int i = 0; i < 40; i++) {
			labels.add("row-" + i);
		}
		return valuesOf(labels);
	}

	private static BindingSetAssignment valuesOf(List<String> labels) {
		List<BindingSet> rows = new ArrayList<>();
		for (String label : labels) {
			MapBindingSet row = new MapBindingSet();
			row.addBinding("x", VF.createLiteral(label));
			rows.add(row);
		}
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of("x"));
		assignment.setBindingSets(rows);
		return assignment;
	}

	private static TupleExpr leftDeep(TupleExpr... factors) {
		TupleExpr result = factors[0];
		for (int i = 1; i < factors.length; i++) {
			result = new Join(result, factors[i]);
		}
		return result;
	}

	private static StatementPattern p(String subject, String object) {
		return new StatementPattern(Var.of(subject), Var.of("_const_p", VF.createIRI("urn:p")), Var.of(object));
	}

	private static StatementPattern q(String subject, String object) {
		return new StatementPattern(Var.of(subject), Var.of("_const_q", VF.createIRI("urn:q")), Var.of(object));
	}
}
